import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { projectLogic } from 'scenes/projectLogic'

import { tasksModelsRetrieve } from 'products/tasks/frontend/generated/api'
import { ModelCatalogueResponseApi, ModelChoiceApi } from 'products/tasks/frontend/generated/api.schemas'

const NO_LISTING: ModelCatalogueResponseApi = { models: [], cost_baseline: '' }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicValues {
    currentProjectId: number | null // projectLogic
    catalogue: ModelChoiceApi[]
    costBaselineLabel: string
    listing: ModelCatalogueResponseApi
    listingLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicActions {
    loadListing: () => any
    loadListingFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadListingSuccess: (
        listing: ModelCatalogueResponseApi,
        payload?: any
    ) => {
        listing: ModelCatalogueResponseApi
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface modelCatalogueLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        catalogue: (listing: ModelCatalogueResponseApi) => ModelChoiceApi[]
        costBaselineLabel: (listing: ModelCatalogueResponseApi) => string
    }
}

export type modelCatalogueLogicType = MakeLogicType<
    modelCatalogueLogicValues,
    modelCatalogueLogicActions,
    Record<string, any>,
    modelCatalogueLogicMeta
>

export const modelCatalogueLogic = kea<modelCatalogueLogicType>([
    path(['products', 'posthog_ai', 'frontend', 'logics', 'modelCatalogueLogic']),

    connect(() => ({
        values: [projectLogic, ['currentProjectId']],
    })),

    loaders(({ values }) => ({
        listing: [
            NO_LISTING,
            {
                loadListing: async () =>
                    values.currentProjectId == null
                        ? NO_LISTING
                        : await tasksModelsRetrieve(String(values.currentProjectId), { include_unoffered: true }),
            },
        ],
    })),

    selectors({
        catalogue: [(s) => [s.listing], (listing: ModelCatalogueResponseApi): ModelChoiceApi[] => listing.models],
        costBaselineLabel: [(s) => [s.listing], (listing: ModelCatalogueResponseApi): string => listing.cost_baseline],
    }),

    afterMount(({ actions }) => {
        actions.loadListing()
    }),
])
